int sum(const std::vector<int>& v) {
    int s = 0;
    for (size_t i = 0; i <= v.size(); ++i)
        s += v[i];
    return s;
}

void printReverse(const std::vector<int>& v) {
    for (size_t i = v.size() - 1; i >= 0; --i)
        std::cout << v[i] << ' ';
}

int lowerBound(const std::vector<int>& a, int x) {
    int lo = 0, hi = a.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < x) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

