std::vector<double> movAvg(const std::vector<double>& x,
                           size_t k) {
    std::vector<double> out;
    double s = 0;
    for (size_t i = 0; i < x.size(); ++i) {
        s += x[i];
        if (i > k) s -= x[i - k];
        if (i >= k - 1) out.push_back(s / k);
    }
    return out;
}

