struct Ring {
    std::array<float, 1024> buf{};
    size_t head = 0;   // next write slot
    size_t count = 0;
    void push(float x) {
        buf[head] = x;
        head = (head + 1) % 1024;
        if (count < 1024) ++count;
    }
    // k = 0 -> newest sample
    float recent(size_t k) const {
        return buf[(head - k) % 1024];
    }
};

bool isSorted(const std::vector<int>& v) {
    for (int i = 0; i < v.size() - 1; ++i)
        if (v[i] > v[i + 1]) return false;
    return true;
}

