size_t numFrames(size_t n, size_t frame, size_t hop) {
    if (n < frame) return 0;          // avoid unsigned underflow
    return (n - frame) / hop + 1;     // first frame + full hops
}
// n=1024, frame=256, hop=128 -> (768/128)+1 = 7
// n=256, frame=256 -> 1;  n=255 -> 0

