// a is sorted and non-empty; returns index or -1
long find(const std::vector<int>& a, int x) {
    size_t lo = 0, hi = a.size() - 1;
    while (lo <= hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (a[mid] == x) return mid;
        if (a[mid] < x) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

