void readLast(const float* buf, size_t N, size_t head,
              size_t n, float* out) {
    size_t start = (head + N - n) % N;      // oldest of the n
    size_t first = std::min(n, N - start);  // until end of buf
    std::memcpy(out, buf + start, first * sizeof(float));
    std::memcpy(out + first, buf, (n - first) * sizeof(float));
}
// N=8, head=1, n=3: start=6, first=2 -> buf[6],buf[7],buf[0]
// n=N: start=head, copies head..N-1 then 0..head-1

