void zero(int* a, int n) {
    for (int i = 0; i <= n; ++i)
        a[i] = 0;
}

void copyStr(char* dst, const char* src, size_t cap) {
    size_t i = 0;
    for (; i < cap; ++i)
        dst[i] = src[i];
    dst[i] = '\0';
}

std::vector<int> closedRange(int a, int b) {
    std::vector<int> v;
    for (int i = a; i < b; ++i)
        v.push_back(i);
    return v;
}

std::string slice(const std::string& s, size_t i, size_t j) {
