}

def moving_diff(xs):
    # xs[i+1] - xs[i] for each adjacent pair
    return [xs[i + 1] - xs[i] for i in range(len(xs))]

// prefix[i] = sum of a[0..i-1]; prefix.size() == a.size()+1
long rangeSum(const std::vector<long>& prefix,
              size_t l, size_t r) {
    return prefix[r] - prefix[l];
}
